arguments.command:
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
echo "x-access-token"
EOF
# Actually need password only sometimes; git asks username then password
cat > /tmp/askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
*Username*) echo "x-access-token" ;;
*Password*) echo "$GITHUB_TOKEN" ;;
*) echo "" ;;
esac
EOF
chmod +x /tmp/askpass.sh
GIT_ASKPASS=/tmp/askpass.sh git -C /tmp/monica-worktree push origin HEAD:refs/heads/friend/monica 2>&1 | tail
